from datetime import datetime
def read_value_for_ts_id(ts_id, timestamp):
    with open(VALUES_CSV, newline='') as f:
        values_reader = csv.DictReader(f)
        for row in values_reader:
            if row['timeseries_id'] == ts_id and row['timestamp'] == timestamp:
                return row['value']
    return None

